// ValidateBusinessMemoryResponseBody runs the validations defined on
// BusinessMemoryResponseBody
func ValidateBusinessMemoryResponseBody(body *BusinessMemoryResponseBody) (err error) {
	if body.ID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("id", "body"))
	}
	if body.Body == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("body", "body"))
	}
	if body.MemoryType == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("memory_type", "body"))
	}
	if body.StructuralScope == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("structural_scope", "body"))
	}
	if body.ContentScope == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("content_scope", "body"))
	}
	if body.EmbeddingModel == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("embedding_model", "body"))
	}
	if body.ExtractionModel == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("extraction_model", "body"))
	}
	if body.SourceChatID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("source_chat_id", "body"))
	}
	if body.ExtractedAt == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("extracted_at", "body"))
	}
	if body.LifecycleState == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("lifecycle_state", "body"))
	}
	if body.ID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.id", *body.ID, goa.FormatUUID))
	}
	if body.MemoryType != nil {
		if !(*body.MemoryType == "glossary" || *body.MemoryType == "procedure" || *body.MemoryType == "result") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.memory_type", *body.MemoryType, []any{"glossary", "procedure", "result"}))
		}
	}
	if body.ExtractedAt != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.extracted_at", *body.ExtractedAt, goa.FormatDateTime))
	}
	return
}

